window.MG_LAZY_DATA["data/lazy/owner-courses/a081-d87c218b31083cf9.json"]={sha256:"d87c218b31083cf952227c16c17a5a211e925ce8e7814aac8d2ba227038841be",value:{"id":"a081","title":"碳化矽磊晶與缺陷控制","titleEn":"Silicon-carbide epitaxy and defect control","category":"semiconductor","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":550,"languageCoverage":["zh-TW","en"],"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic","v8-c-nist-place","v8-c-nist-history","v8-c-nist-metrology","v3-media-80679a241086"],"simulationOnly":true,"summary":"從多型與基板、穿通差排到磊晶放行：以 12 項工程決策、24 個模型與診斷工作包建立證據。","summaryEn":"From Polytype and substrate and Threading dislocations to Epitaxy release: build evidence through twelve engineering decisions and twenty-four modeling/diagnostic work packages.","scope":"公開原理的教學拆解：12 個技術主題各有模型／分析及故障／驗證兩步，共四階段 24 步。不是 24 道實際製造配方，也不是任何廠商量產流程。數值由學員自訂並標示為假設；涉及材料加工、高壓、雷射或化學品的活動僅做圖上與資料分析，不由網頁授權實機操作。","scopeEn":"A public-principles educational decomposition: twelve technical topics each have a model/analysis step and a diagnosis/verification step, organized as four stages and twenty-four work packages. These are not twenty-four fabrication recipes or a manufacturer flow. Learner-selected numbers are hypothetical; materials processing, high voltage, lasers and chemicals are studied through diagrams/data, not authorized physical operation.","diagram":{"type":"wafer","labels":["多型與基板","基面差排","厚度均勻度","缺陷檢出率"],"labelsEn":["Polytype and substrate","Basal-plane dislocations","Thickness uniformity","Defect detectability"],"original":true,"notToScale":true},"stages":[{"id":"a081-stage01","order":1,"title":"多型與基板 → 差排傳承","titleEn":"Polytype and substrate to Dislocation inheritance","description":"把「多型與基板」「偏角與台階」「差排傳承」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Polytype and substrate, Miscut and steps, Dislocation inheritance.","steps":[{"id":"a081-v8-01","order":1,"sequence":1,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":[],"title":"多型與基板：建立模型","titleEn":"Polytype and substrate: construct and analyze","objective":"用可檢查的成果說明「化學成分相同不代表晶體堆疊相同」。","objectiveEn":"Demonstrate the following with inspectable work: Equal chemistry does not imply identical stacking.","instruction":"區分 4H 與其他多型，標記晶向及磊晶面。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Distinguish 4H from other polytypes and label orientation/epitaxial face. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"化學成分相同不代表晶體堆疊相同；相同多型仍可能有不同晶面。","observationEn":"Equal chemistry does not imply identical stacking; The same polytype can have different crystal faces.","failure":"若採用「只看 Si:C 比就確認多型」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Identifying polytype from Si:C ratio alone\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「多型與基板」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：化學成分相同不代表晶體堆疊相同。","checkEn":"Submit the Polytype and substrate diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Equal chemistry does not imply identical stacking.","knowledge":[{"id":"a081-v8-01-k1","title":"多型與基板／物理與模型","titleEn":"Polytype and substrate / Physics and model","text":"機制：化學成分相同不代表晶體堆疊相同。","textEn":"Mechanism: Equal chemistry does not imply identical stacking."},{"id":"a081-v8-01-k2","title":"多型與基板／驗證與限制","titleEn":"Polytype and substrate / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只看 Si:C 比就確認多型」。","textEn":"Model boundary: the current result does not establish the following claim: Identifying polytype from Si:C ratio alone."}],"quiz":{"question":"關於「多型與基板」，哪項推論有物理依據？","questionEn":"For Polytype and substrate, which inference has a physical basis?","options":["化學成分相同不代表晶體堆疊相同","只看 Si:C 比就確認多型","認為偏角是可忽略的幾何誤差"],"optionsEn":["Equal chemistry does not imply identical stacking","Identifying polytype from Si:C ratio alone","Treating miscut as irrelevant geometric error"],"answer":0,"explanation":"化學成分相同不代表晶體堆疊相同；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Equal chemistry does not imply identical stacking. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-02","order":2,"sequence":2,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-01"],"title":"多型與基板：故障判讀與驗證","titleEn":"Polytype and substrate: diagnose and verify","objective":"以新增對照檢查「只看 Si:C 比就確認多型」這項錯誤主張。","objectiveEn":"Test the faulty claim: Identifying polytype from Si:C ratio alone.","instruction":"接續前一步「多型與基板」成果，先指出錯誤主張「只看 Si:C 比就確認多型」漏掉哪個條件。新增診斷原理：相同多型仍可能有不同晶面。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Polytype and substrate artifact. Identify the missing condition in the faulty claim \"Identifying polytype from Si:C ratio alone\". Introduce this diagnostic principle: The same polytype can have different crystal faces. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"化學成分相同不代表晶體堆疊相同；相同多型仍可能有不同晶面。","observationEn":"Equal chemistry does not imply identical stacking; The same polytype can have different crystal faces.","failure":"若採用「只看 Si:C 比就確認多型」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Identifying polytype from Si:C ratio alone\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「多型與基板」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「相同多型仍可能有不同晶面」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Polytype and substrate, its observable and one remaining uncertainty. Explain how \"The same polytype can have different crystal faces\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-02-k1","title":"多型與基板／物理與模型","titleEn":"Polytype and substrate / Physics and model","text":"診斷機制：相同多型仍可能有不同晶面。","textEn":"Diagnostic mechanism: The same polytype can have different crystal faces."},{"id":"a081-v8-02-k2","title":"多型與基板／驗證與限制","titleEn":"Polytype and substrate / Verification and limits","text":"可證偽性：「只看 Si:C 比就確認多型」與「化學成分相同不代表晶體堆疊相同」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Identifying polytype from Si:C ratio alone\" is not equivalent to \"Equal chemistry does not imply identical stacking\"; the control must expose their difference."}],"quiz":{"question":"檢查「多型與基板」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Polytype and substrate?","options":["認為偏角是可忽略的幾何誤差","相同多型仍可能有不同晶面","只看 Si:C 比就確認多型"],"optionsEn":["Treating miscut as irrelevant geometric error","The same polytype can have different crystal faces","Identifying polytype from Si:C ratio alone"],"answer":1,"explanation":"相同多型仍可能有不同晶面；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"The same polytype can have different crystal faces. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-03","order":3,"sequence":3,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-02"],"title":"偏角與台階：建立模型","titleEn":"Miscut and steps: construct and analyze","objective":"用可檢查的成果說明「偏角和表面動力學共同影響成長」。","objectiveEn":"Demonstrate the following with inspectable work: Miscut and surface kinetics jointly affect growth.","instruction":"畫偏角表面台階，比較台階流與二維成核的假說。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Sketch miscut steps and compare step-flow and island-nucleation hypotheses. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"偏角和表面動力學共同影響成長；台階聚集可能改變局部成長形貌。","observationEn":"Miscut and surface kinetics jointly affect growth; Step bunching changes local morphology.","failure":"若採用「認為偏角是可忽略的幾何誤差」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating miscut as irrelevant geometric error\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「偏角與台階」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：偏角和表面動力學共同影響成長。","checkEn":"Submit the Miscut and steps diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Miscut and surface kinetics jointly affect growth.","knowledge":[{"id":"a081-v8-03-k1","title":"偏角與台階／物理與模型","titleEn":"Miscut and steps / Physics and model","text":"機制：偏角和表面動力學共同影響成長。","textEn":"Mechanism: Miscut and surface kinetics jointly affect growth."},{"id":"a081-v8-03-k2","title":"偏角與台階／驗證與限制","titleEn":"Miscut and steps / Verification and limits","text":"模型邊界：不可由目前成果直接推出「認為偏角是可忽略的幾何誤差」。","textEn":"Model boundary: the current result does not establish the following claim: Treating miscut as irrelevant geometric error."}],"quiz":{"question":"關於「偏角與台階」，哪項推論有物理依據？","questionEn":"For Miscut and steps, which inference has a physical basis?","options":["認為偏角是可忽略的幾何誤差","所有磊晶缺陷都由同一成長步驟新生","偏角和表面動力學共同影響成長"],"optionsEn":["Treating miscut as irrelevant geometric error","Assuming all epilayer defects are newly generated","Miscut and surface kinetics jointly affect growth"],"answer":2,"explanation":"偏角和表面動力學共同影響成長；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Miscut and surface kinetics jointly affect growth. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-04","order":4,"sequence":4,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-03"],"title":"偏角與台階：故障判讀與驗證","titleEn":"Miscut and steps: diagnose and verify","objective":"以新增對照檢查「認為偏角是可忽略的幾何誤差」這項錯誤主張。","objectiveEn":"Test the faulty claim: Treating miscut as irrelevant geometric error.","instruction":"接續前一步「偏角與台階」成果，先指出錯誤主張「認為偏角是可忽略的幾何誤差」漏掉哪個條件。新增診斷原理：台階聚集可能改變局部成長形貌。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Miscut and steps artifact. Identify the missing condition in the faulty claim \"Treating miscut as irrelevant geometric error\". Introduce this diagnostic principle: Step bunching changes local morphology. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"偏角和表面動力學共同影響成長；台階聚集可能改變局部成長形貌。","observationEn":"Miscut and surface kinetics jointly affect growth; Step bunching changes local morphology.","failure":"若採用「認為偏角是可忽略的幾何誤差」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating miscut as irrelevant geometric error\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「偏角與台階」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「台階聚集可能改變局部成長形貌」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Miscut and steps, its observable and one remaining uncertainty. Explain how \"Step bunching changes local morphology\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-04-k1","title":"偏角與台階／物理與模型","titleEn":"Miscut and steps / Physics and model","text":"診斷機制：台階聚集可能改變局部成長形貌。","textEn":"Diagnostic mechanism: Step bunching changes local morphology."},{"id":"a081-v8-04-k2","title":"偏角與台階／驗證與限制","titleEn":"Miscut and steps / Verification and limits","text":"可證偽性：「認為偏角是可忽略的幾何誤差」與「偏角和表面動力學共同影響成長」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Treating miscut as irrelevant geometric error\" is not equivalent to \"Miscut and surface kinetics jointly affect growth\"; the control must expose their difference."}],"quiz":{"question":"檢查「偏角與台階」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Miscut and steps?","options":["台階聚集可能改變局部成長形貌","認為偏角是可忽略的幾何誤差","所有磊晶缺陷都由同一成長步驟新生"],"optionsEn":["Step bunching changes local morphology","Treating miscut as irrelevant geometric error","Assuming all epilayer defects are newly generated"],"answer":0,"explanation":"台階聚集可能改變局部成長形貌；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Step bunching changes local morphology. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-05","order":5,"sequence":5,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-04"],"title":"差排傳承：建立模型","titleEn":"Dislocation inheritance: construct and analyze","objective":"用可檢查的成果說明「磊晶品質需要追溯基板缺陷」。","objectiveEn":"Demonstrate the following with inspectable work: Epitaxial quality must be traced to substrate defects.","instruction":"對基板與磊晶缺陷圖配準，區分繼承與新增缺陷。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Register substrate/epilayer maps and separate inherited from new defects. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"磊晶品質需要追溯基板缺陷；配準誤差會造成假新增缺陷。","observationEn":"Epitaxial quality must be traced to substrate defects; Registration error produces false new defects.","failure":"若採用「所有磊晶缺陷都由同一成長步驟新生」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming all epilayer defects are newly generated\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「差排傳承」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：磊晶品質需要追溯基板缺陷。","checkEn":"Submit the Dislocation inheritance diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Epitaxial quality must be traced to substrate defects.","knowledge":[{"id":"a081-v8-05-k1","title":"差排傳承／物理與模型","titleEn":"Dislocation inheritance / Physics and model","text":"機制：磊晶品質需要追溯基板缺陷。","textEn":"Mechanism: Epitaxial quality must be traced to substrate defects."},{"id":"a081-v8-05-k2","title":"差排傳承／驗證與限制","titleEn":"Dislocation inheritance / Verification and limits","text":"模型邊界：不可由目前成果直接推出「所有磊晶缺陷都由同一成長步驟新生」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming all epilayer defects are newly generated."}],"quiz":{"question":"關於「差排傳承」，哪項推論有物理依據？","questionEn":"For Dislocation inheritance, which inference has a physical basis?","options":["出廠缺陷圖能涵蓋所有操作後變化","磊晶品質需要追溯基板缺陷","所有磊晶缺陷都由同一成長步驟新生"],"optionsEn":["Assuming as-grown maps capture every operational change","Epitaxial quality must be traced to substrate defects","Assuming all epilayer defects are newly generated"],"answer":1,"explanation":"磊晶品質需要追溯基板缺陷；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Epitaxial quality must be traced to substrate defects. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-06","order":6,"sequence":6,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-05"],"title":"差排傳承：故障判讀與驗證","titleEn":"Dislocation inheritance: diagnose and verify","objective":"以新增對照檢查「所有磊晶缺陷都由同一成長步驟新生」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming all epilayer defects are newly generated.","instruction":"接續前一步「差排傳承」成果，先指出錯誤主張「所有磊晶缺陷都由同一成長步驟新生」漏掉哪個條件。新增診斷原理：配準誤差會造成假新增缺陷。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Dislocation inheritance artifact. Identify the missing condition in the faulty claim \"Assuming all epilayer defects are newly generated\". Introduce this diagnostic principle: Registration error produces false new defects. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"磊晶品質需要追溯基板缺陷；配準誤差會造成假新增缺陷。","observationEn":"Epitaxial quality must be traced to substrate defects; Registration error produces false new defects.","failure":"若採用「所有磊晶缺陷都由同一成長步驟新生」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming all epilayer defects are newly generated\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「差排傳承」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「配準誤差會造成假新增缺陷」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Dislocation inheritance, its observable and one remaining uncertainty. Explain how \"Registration error produces false new defects\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-06-k1","title":"差排傳承／物理與模型","titleEn":"Dislocation inheritance / Physics and model","text":"診斷機制：配準誤差會造成假新增缺陷。","textEn":"Diagnostic mechanism: Registration error produces false new defects."},{"id":"a081-v8-06-k2","title":"差排傳承／驗證與限制","titleEn":"Dislocation inheritance / Verification and limits","text":"可證偽性：「所有磊晶缺陷都由同一成長步驟新生」與「磊晶品質需要追溯基板缺陷」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming all epilayer defects are newly generated\" is not equivalent to \"Epitaxial quality must be traced to substrate defects\"; the control must expose their difference."}],"quiz":{"question":"檢查「差排傳承」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Dislocation inheritance?","options":["所有磊晶缺陷都由同一成長步驟新生","出廠缺陷圖能涵蓋所有操作後變化","配準誤差會造成假新增缺陷"],"optionsEn":["Assuming all epilayer defects are newly generated","Assuming as-grown maps capture every operational change","Registration error produces false new defects"],"answer":2,"explanation":"配準誤差會造成假新增缺陷；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Registration error produces false new defects. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a081-stage02","order":2,"title":"基面差排 → 表面台階聚集","titleEn":"Basal-plane dislocations to Step bunching","description":"把「基面差排」「穿通差排」「表面台階聚集」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Basal-plane dislocations, Threading dislocations, Step bunching.","steps":[{"id":"a081-v8-07","order":1,"sequence":7,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-06"],"title":"基面差排：建立模型","titleEn":"Basal-plane dislocations: construct and analyze","objective":"用可檢查的成果說明「某些結構缺陷可在載子注入後演化」。","objectiveEn":"Demonstrate the following with inspectable work: Some structural defects evolve after carrier injection.","instruction":"畫基面差排與可能堆疊錯擴展，連到雙極注入的驗證。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw basal dislocations and possible stacking-fault expansion with bipolar-injection checks. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"某些結構缺陷可在載子注入後演化；注入條件決定堆疊錯擴展風險。","observationEn":"Some structural defects evolve after carrier injection; Injection conditions affect fault-expansion risk.","failure":"若採用「出廠缺陷圖能涵蓋所有操作後變化」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming as-grown maps capture every operational change\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「基面差排」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：某些結構缺陷可在載子注入後演化。","checkEn":"Submit the Basal-plane dislocations diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Some structural defects evolve after carrier injection.","knowledge":[{"id":"a081-v8-07-k1","title":"基面差排／物理與模型","titleEn":"Basal-plane dislocations / Physics and model","text":"機制：某些結構缺陷可在載子注入後演化。","textEn":"Mechanism: Some structural defects evolve after carrier injection."},{"id":"a081-v8-07-k2","title":"基面差排／驗證與限制","titleEn":"Basal-plane dislocations / Verification and limits","text":"模型邊界：不可由目前成果直接推出「出廠缺陷圖能涵蓋所有操作後變化」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming as-grown maps capture every operational change."}],"quiz":{"question":"關於「基面差排」，哪項推論有物理依據？","questionEn":"For Basal-plane dislocations, which inference has a physical basis?","options":["某些結構缺陷可在載子注入後演化","出廠缺陷圖能涵蓋所有操作後變化","所有暗點都標為相同差排類型"],"optionsEn":["Some structural defects evolve after carrier injection","Assuming as-grown maps capture every operational change","Labeling all dark spots the same dislocation"],"answer":0,"explanation":"某些結構缺陷可在載子注入後演化；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Some structural defects evolve after carrier injection. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-08","order":2,"sequence":8,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-07"],"title":"基面差排：故障判讀與驗證","titleEn":"Basal-plane dislocations: diagnose and verify","objective":"以新增對照檢查「出廠缺陷圖能涵蓋所有操作後變化」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming as-grown maps capture every operational change.","instruction":"接續前一步「基面差排」成果，先指出錯誤主張「出廠缺陷圖能涵蓋所有操作後變化」漏掉哪個條件。新增診斷原理：注入條件決定堆疊錯擴展風險。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Basal-plane dislocations artifact. Identify the missing condition in the faulty claim \"Assuming as-grown maps capture every operational change\". Introduce this diagnostic principle: Injection conditions affect fault-expansion risk. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"某些結構缺陷可在載子注入後演化；注入條件決定堆疊錯擴展風險。","observationEn":"Some structural defects evolve after carrier injection; Injection conditions affect fault-expansion risk.","failure":"若採用「出廠缺陷圖能涵蓋所有操作後變化」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming as-grown maps capture every operational change\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「基面差排」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「注入條件決定堆疊錯擴展風險」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Basal-plane dislocations, its observable and one remaining uncertainty. Explain how \"Injection conditions affect fault-expansion risk\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-08-k1","title":"基面差排／物理與模型","titleEn":"Basal-plane dislocations / Physics and model","text":"診斷機制：注入條件決定堆疊錯擴展風險。","textEn":"Diagnostic mechanism: Injection conditions affect fault-expansion risk."},{"id":"a081-v8-08-k2","title":"基面差排／驗證與限制","titleEn":"Basal-plane dislocations / Verification and limits","text":"可證偽性：「出廠缺陷圖能涵蓋所有操作後變化」與「某些結構缺陷可在載子注入後演化」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming as-grown maps capture every operational change\" is not equivalent to \"Some structural defects evolve after carrier injection\"; the control must expose their difference."}],"quiz":{"question":"檢查「基面差排」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Basal-plane dislocations?","options":["所有暗點都標為相同差排類型","注入條件決定堆疊錯擴展風險","出廠缺陷圖能涵蓋所有操作後變化"],"optionsEn":["Labeling all dark spots the same dislocation","Injection conditions affect fault-expansion risk","Assuming as-grown maps capture every operational change"],"answer":1,"explanation":"注入條件決定堆疊錯擴展風險；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Injection conditions affect fault-expansion risk. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-09","order":3,"sequence":9,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-08"],"title":"穿通差排：建立模型","titleEn":"Threading dislocations: construct and analyze","objective":"用可檢查的成果說明「不同差排不能只靠同一表面暗點分類」。","objectiveEn":"Demonstrate the following with inspectable work: Different dislocations cannot be classified from one dark spot alone.","instruction":"區分刃型與螺型差排的幾何，列出成像交叉證據。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Distinguish threading edge/screw geometry and list cross-imaging evidence. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"不同差排不能只靠同一表面暗點分類；缺陷分類需校正檢查方法靈敏度。","observationEn":"Different dislocations cannot be classified from one dark spot alone; Classification requires detection-sensitivity context.","failure":"若採用「所有暗點都標為相同差排類型」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Labeling all dark spots the same dislocation\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「穿通差排」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：不同差排不能只靠同一表面暗點分類。","checkEn":"Submit the Threading dislocations diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Different dislocations cannot be classified from one dark spot alone.","knowledge":[{"id":"a081-v8-09-k1","title":"穿通差排／物理與模型","titleEn":"Threading dislocations / Physics and model","text":"機制：不同差排不能只靠同一表面暗點分類。","textEn":"Mechanism: Different dislocations cannot be classified from one dark spot alone."},{"id":"a081-v8-09-k2","title":"穿通差排／驗證與限制","titleEn":"Threading dislocations / Verification and limits","text":"模型邊界：不可由目前成果直接推出「所有暗點都標為相同差排類型」。","textEn":"Model boundary: the current result does not establish the following claim: Labeling all dark spots the same dislocation."}],"quiz":{"question":"關於「穿通差排」，哪項推論有物理依據？","questionEn":"For Threading dislocations, which inference has a physical basis?","options":["所有暗點都標為相同差排類型","不同掃描面積的 RMS 可直接排名","不同差排不能只靠同一表面暗點分類"],"optionsEn":["Labeling all dark spots the same dislocation","Ranking RMS values from different scan areas","Different dislocations cannot be classified from one dark spot alone"],"answer":2,"explanation":"不同差排不能只靠同一表面暗點分類；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Different dislocations cannot be classified from one dark spot alone. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-10","order":4,"sequence":10,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-09"],"title":"穿通差排：故障判讀與驗證","titleEn":"Threading dislocations: diagnose and verify","objective":"以新增對照檢查「所有暗點都標為相同差排類型」這項錯誤主張。","objectiveEn":"Test the faulty claim: Labeling all dark spots the same dislocation.","instruction":"接續前一步「穿通差排」成果，先指出錯誤主張「所有暗點都標為相同差排類型」漏掉哪個條件。新增診斷原理：缺陷分類需校正檢查方法靈敏度。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Threading dislocations artifact. Identify the missing condition in the faulty claim \"Labeling all dark spots the same dislocation\". Introduce this diagnostic principle: Classification requires detection-sensitivity context. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"不同差排不能只靠同一表面暗點分類；缺陷分類需校正檢查方法靈敏度。","observationEn":"Different dislocations cannot be classified from one dark spot alone; Classification requires detection-sensitivity context.","failure":"若採用「所有暗點都標為相同差排類型」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Labeling all dark spots the same dislocation\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「穿通差排」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「缺陷分類需校正檢查方法靈敏度」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Threading dislocations, its observable and one remaining uncertainty. Explain how \"Classification requires detection-sensitivity context\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-10-k1","title":"穿通差排／物理與模型","titleEn":"Threading dislocations / Physics and model","text":"診斷機制：缺陷分類需校正檢查方法靈敏度。","textEn":"Diagnostic mechanism: Classification requires detection-sensitivity context."},{"id":"a081-v8-10-k2","title":"穿通差排／驗證與限制","titleEn":"Threading dislocations / Verification and limits","text":"可證偽性：「所有暗點都標為相同差排類型」與「不同差排不能只靠同一表面暗點分類」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Labeling all dark spots the same dislocation\" is not equivalent to \"Different dislocations cannot be classified from one dark spot alone\"; the control must expose their difference."}],"quiz":{"question":"檢查「穿通差排」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Threading dislocations?","options":["缺陷分類需校正檢查方法靈敏度","所有暗點都標為相同差排類型","不同掃描面積的 RMS 可直接排名"],"optionsEn":["Classification requires detection-sensitivity context","Labeling all dark spots the same dislocation","Ranking RMS values from different scan areas"],"answer":0,"explanation":"缺陷分類需校正檢查方法靈敏度；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Classification requires detection-sensitivity context. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-11","order":5,"sequence":11,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-10"],"title":"表面台階聚集：建立模型","titleEn":"Step bunching: construct and analyze","objective":"用可檢查的成果說明「粗糙度需連同空間尺度解讀」。","objectiveEn":"Demonstrate the following with inspectable work: Roughness must be interpreted with spatial scale.","instruction":"畫等距台階與聚集台階，計算相同掃描尺度的高度起伏。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Compare regular/bunched steps at the same scan scale. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"粗糙度需連同空間尺度解讀；AFM 尖端形狀會影響量測輪廓。","observationEn":"Roughness must be interpreted with spatial scale; AFM-tip geometry affects measured profiles.","failure":"若採用「不同掃描面積的 RMS 可直接排名」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Ranking RMS values from different scan areas\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「表面台階聚集」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：粗糙度需連同空間尺度解讀。","checkEn":"Submit the Step bunching diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Roughness must be interpreted with spatial scale.","knowledge":[{"id":"a081-v8-11-k1","title":"表面台階聚集／物理與模型","titleEn":"Step bunching / Physics and model","text":"機制：粗糙度需連同空間尺度解讀。","textEn":"Mechanism: Roughness must be interpreted with spatial scale."},{"id":"a081-v8-11-k2","title":"表面台階聚集／驗證與限制","titleEn":"Step bunching / Verification and limits","text":"模型邊界：不可由目前成果直接推出「不同掃描面積的 RMS 可直接排名」。","textEn":"Model boundary: the current result does not establish the following claim: Ranking RMS values from different scan areas."}],"quiz":{"question":"關於「表面台階聚集」，哪項推論有物理依據？","questionEn":"For Step bunching, which inference has a physical basis?","options":["中心厚度合格就代表全片耐壓一致","粗糙度需連同空間尺度解讀","不同掃描面積的 RMS 可直接排名"],"optionsEn":["Inferring uniform blocking capability from center thickness","Roughness must be interpreted with spatial scale","Ranking RMS values from different scan areas"],"answer":1,"explanation":"粗糙度需連同空間尺度解讀；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Roughness must be interpreted with spatial scale. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-12","order":6,"sequence":12,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-11"],"title":"表面台階聚集：故障判讀與驗證","titleEn":"Step bunching: diagnose and verify","objective":"以新增對照檢查「不同掃描面積的 RMS 可直接排名」這項錯誤主張。","objectiveEn":"Test the faulty claim: Ranking RMS values from different scan areas.","instruction":"接續前一步「表面台階聚集」成果，先指出錯誤主張「不同掃描面積的 RMS 可直接排名」漏掉哪個條件。新增診斷原理：AFM 尖端形狀會影響量測輪廓。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Step bunching artifact. Identify the missing condition in the faulty claim \"Ranking RMS values from different scan areas\". Introduce this diagnostic principle: AFM-tip geometry affects measured profiles. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"粗糙度需連同空間尺度解讀；AFM 尖端形狀會影響量測輪廓。","observationEn":"Roughness must be interpreted with spatial scale; AFM-tip geometry affects measured profiles.","failure":"若採用「不同掃描面積的 RMS 可直接排名」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Ranking RMS values from different scan areas\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「表面台階聚集」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「AFM 尖端形狀會影響量測輪廓」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Step bunching, its observable and one remaining uncertainty. Explain how \"AFM-tip geometry affects measured profiles\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-12-k1","title":"表面台階聚集／物理與模型","titleEn":"Step bunching / Physics and model","text":"診斷機制：AFM 尖端形狀會影響量測輪廓。","textEn":"Diagnostic mechanism: AFM-tip geometry affects measured profiles."},{"id":"a081-v8-12-k2","title":"表面台階聚集／驗證與限制","titleEn":"Step bunching / Verification and limits","text":"可證偽性：「不同掃描面積的 RMS 可直接排名」與「粗糙度需連同空間尺度解讀」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Ranking RMS values from different scan areas\" is not equivalent to \"Roughness must be interpreted with spatial scale\"; the control must expose their difference."}],"quiz":{"question":"檢查「表面台階聚集」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Step bunching?","options":["不同掃描面積的 RMS 可直接排名","中心厚度合格就代表全片耐壓一致","AFM 尖端形狀會影響量測輪廓"],"optionsEn":["Ranking RMS values from different scan areas","Inferring uniform blocking capability from center thickness","AFM-tip geometry affects measured profiles"],"answer":2,"explanation":"AFM 尖端形狀會影響量測輪廓；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"AFM-tip geometry affects measured profiles. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a081-stage03","order":3,"title":"厚度均勻度 → 表面污染","titleEn":"Thickness uniformity to Surface contamination","description":"把「厚度均勻度」「摻雜分布」「表面污染」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Thickness uniformity, Doping distribution, Surface contamination.","steps":[{"id":"a081-v8-13","order":1,"sequence":13,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-12"],"title":"厚度均勻度：建立模型","titleEn":"Thickness uniformity: construct and analyze","objective":"用可檢查的成果說明「一個中心點無法代表全片漂移層」。","objectiveEn":"Demonstrate the following with inspectable work: One center point cannot represent the whole drift layer.","instruction":"建立徑向厚度圖並分開片內與片間偏差。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。\n\n具體算例（全部數值為教學假設）：假設三個外延厚度測點為 99、100、101 µm，平均 100 µm、極差 2 µm。若僅描述這三點、使用母體定義，標準差 sqrt(2/3)=0.8165 µm，變異係數 0.8165%；若作樣本估計則標準差為 1 µm。必須寫明分母，且三點不能推論整片缺陷密度。","instructionEn":"Map radial thickness and separate within-wafer from wafer-to-wafer variation. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.\n\nWorked example (all values are hypothetical teaching inputs): Assume three epitaxial thickness readings of 99, 100 and 101 µm. Mean is 100 µm and range 2 µm. Describing just these points with the population definition gives standard deviation sqrt(2/3)=0.8165 µm and CV=0.8165%; the sample estimate instead gives 1 µm. State the denominator; three sites cannot establish wafer-wide defect density.","observation":"一個中心點無法代表全片漂移層；厚度與摻雜分布可能相互相關。","observationEn":"One center point cannot represent the whole drift layer; Thickness and doping variations may correlate.","failure":"若採用「中心厚度合格就代表全片耐壓一致」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Inferring uniform blocking capability from center thickness\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「厚度均勻度」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：一個中心點無法代表全片漂移層。\n算例驗收：驗算平均、極差及兩種標準差，並在圖上註明取樣位置不足的限制。","checkEn":"Submit the Thickness uniformity diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: One center point cannot represent the whole drift layer.\nWorked-example acceptance: Verify mean, range and both standard-deviation definitions and mark the sampling limitation on the map.","knowledge":[{"id":"a081-v8-13-k1","title":"厚度均勻度／物理與模型","titleEn":"Thickness uniformity / Physics and model","text":"機制：一個中心點無法代表全片漂移層。","textEn":"Mechanism: One center point cannot represent the whole drift layer."},{"id":"a081-v8-13-k2","title":"厚度均勻度／驗證與限制","titleEn":"Thickness uniformity / Verification and limits","text":"模型邊界：不可由目前成果直接推出「中心厚度合格就代表全片耐壓一致」。\n假設數值與推算：假設三個外延厚度測點為 99、100、101 µm，平均 100 µm、極差 2 µm。若僅描述這三點、使用母體定義，標準差 sqrt(2/3)=0.8165 µm，變異係數 0.8165%；若作樣本估計則標準差為 1 µm。必須寫明分母，且三點不能推論整片缺陷密度。","textEn":"Model boundary: the current result does not establish the following claim: Inferring uniform blocking capability from center thickness.\nHypothetical inputs and calculation: Assume three epitaxial thickness readings of 99, 100 and 101 µm. Mean is 100 µm and range 2 µm. Describing just these points with the population definition gives standard deviation sqrt(2/3)=0.8165 µm and CV=0.8165%; the sample estimate instead gives 1 µm. State the denominator; three sites cannot establish wafer-wide defect density."}],"quiz":{"question":"關於「厚度均勻度」，哪項推論有物理依據？","questionEn":"For Thickness uniformity, which inference has a physical basis?","options":["一個中心點無法代表全片漂移層","中心厚度合格就代表全片耐壓一致","只減少摻雜就無代價提升耐壓"],"optionsEn":["One center point cannot represent the whole drift layer","Inferring uniform blocking capability from center thickness","Assuming reduced doping improves blocking without cost"],"answer":0,"explanation":"一個中心點無法代表全片漂移層；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"One center point cannot represent the whole drift layer. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-14","order":2,"sequence":14,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-13"],"title":"厚度均勻度：故障判讀與驗證","titleEn":"Thickness uniformity: diagnose and verify","objective":"以新增對照檢查「中心厚度合格就代表全片耐壓一致」這項錯誤主張。","objectiveEn":"Test the faulty claim: Inferring uniform blocking capability from center thickness.","instruction":"接續前一步「厚度均勻度」成果，先指出錯誤主張「中心厚度合格就代表全片耐壓一致」漏掉哪個條件。新增診斷原理：厚度與摻雜分布可能相互相關。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Thickness uniformity artifact. Identify the missing condition in the faulty claim \"Inferring uniform blocking capability from center thickness\". Introduce this diagnostic principle: Thickness and doping variations may correlate. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"一個中心點無法代表全片漂移層；厚度與摻雜分布可能相互相關。","observationEn":"One center point cannot represent the whole drift layer; Thickness and doping variations may correlate.","failure":"若採用「中心厚度合格就代表全片耐壓一致」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Inferring uniform blocking capability from center thickness\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「厚度均勻度」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「厚度與摻雜分布可能相互相關」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Thickness uniformity, its observable and one remaining uncertainty. Explain how \"Thickness and doping variations may correlate\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-14-k1","title":"厚度均勻度／物理與模型","titleEn":"Thickness uniformity / Physics and model","text":"診斷機制：厚度與摻雜分布可能相互相關。","textEn":"Diagnostic mechanism: Thickness and doping variations may correlate."},{"id":"a081-v8-14-k2","title":"厚度均勻度／驗證與限制","titleEn":"Thickness uniformity / Verification and limits","text":"可證偽性：「中心厚度合格就代表全片耐壓一致」與「一個中心點無法代表全片漂移層」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Inferring uniform blocking capability from center thickness\" is not equivalent to \"One center point cannot represent the whole drift layer\"; the control must expose their difference."}],"quiz":{"question":"檢查「厚度均勻度」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Thickness uniformity?","options":["只減少摻雜就無代價提升耐壓","厚度與摻雜分布可能相互相關","中心厚度合格就代表全片耐壓一致"],"optionsEn":["Assuming reduced doping improves blocking without cost","Thickness and doping variations may correlate","Inferring uniform blocking capability from center thickness"],"answer":1,"explanation":"厚度與摻雜分布可能相互相關；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Thickness and doping variations may correlate. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-15","order":3,"sequence":15,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-14"],"title":"摻雜分布：建立模型","titleEn":"Doping distribution: construct and analyze","objective":"用可檢查的成果說明「厚度與摻雜需共同設計」。","objectiveEn":"Demonstrate the following with inspectable work: Thickness and doping need joint design.","instruction":"對厚度和載子濃度建立雙圖，解釋阻斷與導通取捨。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Map thickness/carrier concentration together and discuss blocking/conduction tradeoffs. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"厚度與摻雜需共同設計；電性濃度不一定等於化學總濃度。","observationEn":"Thickness and doping need joint design; Electrical concentration differs from total chemistry.","failure":"若採用「只減少摻雜就無代價提升耐壓」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming reduced doping improves blocking without cost\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「摻雜分布」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：厚度與摻雜需共同設計。","checkEn":"Submit the Doping distribution diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Thickness and doping need joint design.","knowledge":[{"id":"a081-v8-15-k1","title":"摻雜分布／物理與模型","titleEn":"Doping distribution / Physics and model","text":"機制：厚度與摻雜需共同設計。","textEn":"Mechanism: Thickness and doping need joint design."},{"id":"a081-v8-15-k2","title":"摻雜分布／驗證與限制","titleEn":"Doping distribution / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只減少摻雜就無代價提升耐壓」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming reduced doping improves blocking without cost."}],"quiz":{"question":"關於「摻雜分布」，哪項推論有物理依據？","questionEn":"For Doping distribution, which inference has a physical basis?","options":["只減少摻雜就無代價提升耐壓","晶體 X 光合格就證明表面潔淨","厚度與摻雜需共同設計"],"optionsEn":["Assuming reduced doping improves blocking without cost","Inferring surface cleanliness from crystal X-ray quality","Thickness and doping need joint design"],"answer":2,"explanation":"厚度與摻雜需共同設計；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Thickness and doping need joint design. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-16","order":4,"sequence":16,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-15"],"title":"摻雜分布：故障判讀與驗證","titleEn":"Doping distribution: diagnose and verify","objective":"以新增對照檢查「只減少摻雜就無代價提升耐壓」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming reduced doping improves blocking without cost.","instruction":"接續前一步「摻雜分布」成果，先指出錯誤主張「只減少摻雜就無代價提升耐壓」漏掉哪個條件。新增診斷原理：電性濃度不一定等於化學總濃度。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Doping distribution artifact. Identify the missing condition in the faulty claim \"Assuming reduced doping improves blocking without cost\". Introduce this diagnostic principle: Electrical concentration differs from total chemistry. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"厚度與摻雜需共同設計；電性濃度不一定等於化學總濃度。","observationEn":"Thickness and doping need joint design; Electrical concentration differs from total chemistry.","failure":"若採用「只減少摻雜就無代價提升耐壓」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming reduced doping improves blocking without cost\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「摻雜分布」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「電性濃度不一定等於化學總濃度」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Doping distribution, its observable and one remaining uncertainty. Explain how \"Electrical concentration differs from total chemistry\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-16-k1","title":"摻雜分布／物理與模型","titleEn":"Doping distribution / Physics and model","text":"診斷機制：電性濃度不一定等於化學總濃度。","textEn":"Diagnostic mechanism: Electrical concentration differs from total chemistry."},{"id":"a081-v8-16-k2","title":"摻雜分布／驗證與限制","titleEn":"Doping distribution / Verification and limits","text":"可證偽性：「只減少摻雜就無代價提升耐壓」與「厚度與摻雜需共同設計」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming reduced doping improves blocking without cost\" is not equivalent to \"Thickness and doping need joint design\"; the control must expose their difference."}],"quiz":{"question":"檢查「摻雜分布」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Doping distribution?","options":["電性濃度不一定等於化學總濃度","只減少摻雜就無代價提升耐壓","晶體 X 光合格就證明表面潔淨"],"optionsEn":["Electrical concentration differs from total chemistry","Assuming reduced doping improves blocking without cost","Inferring surface cleanliness from crystal X-ray quality"],"answer":0,"explanation":"電性濃度不一定等於化學總濃度；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Electrical concentration differs from total chemistry. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-17","order":5,"sequence":17,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-16"],"title":"表面污染：建立模型","titleEn":"Surface contamination: construct and analyze","objective":"用可檢查的成果說明「清潔度與晶體缺陷是不同問題」。","objectiveEn":"Demonstrate the following with inspectable work: Cleanliness and crystallographic defects are different issues.","instruction":"把粒子、殘碳及刮傷分開，選擇各自靈敏的檢查。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Separate particles, carbon residue and scratches with suitable inspections. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"清潔度與晶體缺陷是不同問題；清洗也可能改变表面終止態。","observationEn":"Cleanliness and crystallographic defects are different issues; Cleaning can change surface termination.","failure":"若採用「晶體 X 光合格就證明表面潔淨」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Inferring surface cleanliness from crystal X-ray quality\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「表面污染」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：清潔度與晶體缺陷是不同問題。","checkEn":"Submit the Surface contamination diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Cleanliness and crystallographic defects are different issues.","knowledge":[{"id":"a081-v8-17-k1","title":"表面污染／物理與模型","titleEn":"Surface contamination / Physics and model","text":"機制：清潔度與晶體缺陷是不同問題。","textEn":"Mechanism: Cleanliness and crystallographic defects are different issues."},{"id":"a081-v8-17-k2","title":"表面污染／驗證與限制","titleEn":"Surface contamination / Verification and limits","text":"模型邊界：不可由目前成果直接推出「晶體 X 光合格就證明表面潔淨」。","textEn":"Model boundary: the current result does not establish the following claim: Inferring surface cleanliness from crystal X-ray quality."}],"quiz":{"question":"關於「表面污染」，哪項推論有物理依據？","questionEn":"For Surface contamination, which inference has a physical basis?","options":["某法未看見就證明缺陷不存在","清潔度與晶體缺陷是不同問題","晶體 X 光合格就證明表面潔淨"],"optionsEn":["Taking non-detection by one method as absence","Cleanliness and crystallographic defects are different issues","Inferring surface cleanliness from crystal X-ray quality"],"answer":1,"explanation":"清潔度與晶體缺陷是不同問題；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Cleanliness and crystallographic defects are different issues. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-18","order":6,"sequence":18,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-17"],"title":"表面污染：故障判讀與驗證","titleEn":"Surface contamination: diagnose and verify","objective":"以新增對照檢查「晶體 X 光合格就證明表面潔淨」這項錯誤主張。","objectiveEn":"Test the faulty claim: Inferring surface cleanliness from crystal X-ray quality.","instruction":"接續前一步「表面污染」成果，先指出錯誤主張「晶體 X 光合格就證明表面潔淨」漏掉哪個條件。新增診斷原理：清洗也可能改变表面終止態。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Surface contamination artifact. Identify the missing condition in the faulty claim \"Inferring surface cleanliness from crystal X-ray quality\". Introduce this diagnostic principle: Cleaning can change surface termination. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"清潔度與晶體缺陷是不同問題；清洗也可能改变表面終止態。","observationEn":"Cleanliness and crystallographic defects are different issues; Cleaning can change surface termination.","failure":"若採用「晶體 X 光合格就證明表面潔淨」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Inferring surface cleanliness from crystal X-ray quality\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「表面污染」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「清洗也可能改变表面終止態」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Surface contamination, its observable and one remaining uncertainty. Explain how \"Cleaning can change surface termination\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-18-k1","title":"表面污染／物理與模型","titleEn":"Surface contamination / Physics and model","text":"診斷機制：清洗也可能改变表面終止態。","textEn":"Diagnostic mechanism: Cleaning can change surface termination."},{"id":"a081-v8-18-k2","title":"表面污染／驗證與限制","titleEn":"Surface contamination / Verification and limits","text":"可證偽性：「晶體 X 光合格就證明表面潔淨」與「清潔度與晶體缺陷是不同問題」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Inferring surface cleanliness from crystal X-ray quality\" is not equivalent to \"Cleanliness and crystallographic defects are different issues\"; the control must expose their difference."}],"quiz":{"question":"檢查「表面污染」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Surface contamination?","options":["晶體 X 光合格就證明表面潔淨","某法未看見就證明缺陷不存在","清洗也可能改变表面終止態"],"optionsEn":["Inferring surface cleanliness from crystal X-ray quality","Taking non-detection by one method as absence","Cleaning can change surface termination"],"answer":2,"explanation":"清洗也可能改变表面終止態；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Cleaning can change surface termination. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a081-stage04","order":4,"title":"缺陷檢出率 → 磊晶放行","titleEn":"Defect detectability to Epitaxy release","description":"把「缺陷檢出率」「晶粒接受區」「磊晶放行」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Defect detectability, Die acceptance regions, Epitaxy release.","steps":[{"id":"a081-v8-19","order":1,"sequence":19,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-18"],"title":"缺陷檢出率：建立模型","titleEn":"Defect detectability: construct and analyze","objective":"用可檢查的成果說明「不同方法對同一缺陷的可見性不同」。","objectiveEn":"Demonstrate the following with inspectable work: Methods have different visibility for a given defect.","instruction":"將光致發光、表面影像與電性圖配對，記錄各法盲點。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Correlate photoluminescence, surface images and electrical maps with blind spots. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"不同方法對同一缺陷的可見性不同；漏檢與誤檢都應量化。","observationEn":"Methods have different visibility for a given defect; Quantify misses as well as false detections.","failure":"若採用「某法未看見就證明缺陷不存在」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Taking non-detection by one method as absence\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「缺陷檢出率」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：不同方法對同一缺陷的可見性不同。","checkEn":"Submit the Defect detectability diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Methods have different visibility for a given defect.","knowledge":[{"id":"a081-v8-19-k1","title":"缺陷檢出率／物理與模型","titleEn":"Defect detectability / Physics and model","text":"機制：不同方法對同一缺陷的可見性不同。","textEn":"Mechanism: Methods have different visibility for a given defect."},{"id":"a081-v8-19-k2","title":"缺陷檢出率／驗證與限制","titleEn":"Defect detectability / Verification and limits","text":"模型邊界：不可由目前成果直接推出「某法未看見就證明缺陷不存在」。","textEn":"Model boundary: the current result does not establish the following claim: Taking non-detection by one method as absence."}],"quiz":{"question":"關於「缺陷檢出率」，哪項推論有物理依據？","questionEn":"For Defect detectability, which inference has a physical basis?","options":["不同方法對同一缺陷的可見性不同","某法未看見就證明缺陷不存在","每顆缺陷都以同一方式殺死所有晶粒"],"optionsEn":["Methods have different visibility for a given defect","Taking non-detection by one method as absence","Assuming every defect kills every die equally"],"answer":0,"explanation":"不同方法對同一缺陷的可見性不同；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Methods have different visibility for a given defect. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-20","order":2,"sequence":20,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-19"],"title":"缺陷檢出率：故障判讀與驗證","titleEn":"Defect detectability: diagnose and verify","objective":"以新增對照檢查「某法未看見就證明缺陷不存在」這項錯誤主張。","objectiveEn":"Test the faulty claim: Taking non-detection by one method as absence.","instruction":"接續前一步「缺陷檢出率」成果，先指出錯誤主張「某法未看見就證明缺陷不存在」漏掉哪個條件。新增診斷原理：漏檢與誤檢都應量化。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Defect detectability artifact. Identify the missing condition in the faulty claim \"Taking non-detection by one method as absence\". Introduce this diagnostic principle: Quantify misses as well as false detections. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"不同方法對同一缺陷的可見性不同；漏檢與誤檢都應量化。","observationEn":"Methods have different visibility for a given defect; Quantify misses as well as false detections.","failure":"若採用「某法未看見就證明缺陷不存在」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Taking non-detection by one method as absence\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「缺陷檢出率」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「漏檢與誤檢都應量化」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Defect detectability, its observable and one remaining uncertainty. Explain how \"Quantify misses as well as false detections\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-20-k1","title":"缺陷檢出率／物理與模型","titleEn":"Defect detectability / Physics and model","text":"診斷機制：漏檢與誤檢都應量化。","textEn":"Diagnostic mechanism: Quantify misses as well as false detections."},{"id":"a081-v8-20-k2","title":"缺陷檢出率／驗證與限制","titleEn":"Defect detectability / Verification and limits","text":"可證偽性：「某法未看見就證明缺陷不存在」與「不同方法對同一缺陷的可見性不同」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Taking non-detection by one method as absence\" is not equivalent to \"Methods have different visibility for a given defect\"; the control must expose their difference."}],"quiz":{"question":"檢查「缺陷檢出率」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Defect detectability?","options":["每顆缺陷都以同一方式殺死所有晶粒","漏檢與誤檢都應量化","某法未看見就證明缺陷不存在"],"optionsEn":["Assuming every defect kills every die equally","Quantify misses as well as false detections","Taking non-detection by one method as absence"],"answer":1,"explanation":"漏檢與誤檢都應量化；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Quantify misses as well as false detections. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-21","order":3,"sequence":21,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-20"],"title":"晶粒接受區：建立模型","titleEn":"Die acceptance regions: construct and analyze","objective":"用可檢查的成果說明「缺陷風險取決於位置與元件敏感度」。","objectiveEn":"Demonstrate the following with inspectable work: Defect risk depends on location and device sensitivity.","instruction":"將缺陷座標覆到假設晶粒版圖，區分主動區與外圍。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Overlay defects on hypothetical dies and separate active regions from periphery. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"缺陷風險取決於位置與元件敏感度；元件終端區也可能對缺陷敏感。","observationEn":"Defect risk depends on location and device sensitivity; Device termination can also be defect-sensitive.","failure":"若採用「每顆缺陷都以同一方式殺死所有晶粒」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming every defect kills every die equally\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「晶粒接受區」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：缺陷風險取決於位置與元件敏感度。","checkEn":"Submit the Die acceptance regions diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Defect risk depends on location and device sensitivity.","knowledge":[{"id":"a081-v8-21-k1","title":"晶粒接受區／物理與模型","titleEn":"Die acceptance regions / Physics and model","text":"機制：缺陷風險取決於位置與元件敏感度。","textEn":"Mechanism: Defect risk depends on location and device sensitivity."},{"id":"a081-v8-21-k2","title":"晶粒接受區／驗證與限制","titleEn":"Die acceptance regions / Verification and limits","text":"模型邊界：不可由目前成果直接推出「每顆缺陷都以同一方式殺死所有晶粒」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming every defect kills every die equally."}],"quiz":{"question":"關於「晶粒接受區」，哪項推論有物理依據？","questionEn":"For Die acceptance regions, which inference has a physical basis?","options":["每顆缺陷都以同一方式殺死所有晶粒","只選缺陷密度最低批次而忽略其他規格","缺陷風險取決於位置與元件敏感度"],"optionsEn":["Assuming every defect kills every die equally","Selecting minimum defect density while ignoring other requirements","Defect risk depends on location and device sensitivity"],"answer":2,"explanation":"缺陷風險取決於位置與元件敏感度；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Defect risk depends on location and device sensitivity. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-22","order":4,"sequence":22,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-21"],"title":"晶粒接受區：故障判讀與驗證","titleEn":"Die acceptance regions: diagnose and verify","objective":"以新增對照檢查「每顆缺陷都以同一方式殺死所有晶粒」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming every defect kills every die equally.","instruction":"接續前一步「晶粒接受區」成果，先指出錯誤主張「每顆缺陷都以同一方式殺死所有晶粒」漏掉哪個條件。新增診斷原理：元件終端區也可能對缺陷敏感。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Die acceptance regions artifact. Identify the missing condition in the faulty claim \"Assuming every defect kills every die equally\". Introduce this diagnostic principle: Device termination can also be defect-sensitive. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"缺陷風險取決於位置與元件敏感度；元件終端區也可能對缺陷敏感。","observationEn":"Defect risk depends on location and device sensitivity; Device termination can also be defect-sensitive.","failure":"若採用「每顆缺陷都以同一方式殺死所有晶粒」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming every defect kills every die equally\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「晶粒接受區」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「元件終端區也可能對缺陷敏感」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Die acceptance regions, its observable and one remaining uncertainty. Explain how \"Device termination can also be defect-sensitive\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-22-k1","title":"晶粒接受區／物理與模型","titleEn":"Die acceptance regions / Physics and model","text":"診斷機制：元件終端區也可能對缺陷敏感。","textEn":"Diagnostic mechanism: Device termination can also be defect-sensitive."},{"id":"a081-v8-22-k2","title":"晶粒接受區／驗證與限制","titleEn":"Die acceptance regions / Verification and limits","text":"可證偽性：「每顆缺陷都以同一方式殺死所有晶粒」與「缺陷風險取決於位置與元件敏感度」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming every defect kills every die equally\" is not equivalent to \"Defect risk depends on location and device sensitivity\"; the control must expose their difference."}],"quiz":{"question":"檢查「晶粒接受區」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Die acceptance regions?","options":["元件終端區也可能對缺陷敏感","每顆缺陷都以同一方式殺死所有晶粒","只選缺陷密度最低批次而忽略其他規格"],"optionsEn":["Device termination can also be defect-sensitive","Assuming every defect kills every die equally","Selecting minimum defect density while ignoring other requirements"],"answer":0,"explanation":"元件終端區也可能對缺陷敏感；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Device termination can also be defect-sensitive. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-23","order":5,"sequence":23,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-22"],"title":"磊晶放行：建立模型","titleEn":"Epitaxy release: construct and analyze","objective":"用可檢查的成果說明「磊晶放行須連到後續元件需求」。","objectiveEn":"Demonstrate the following with inspectable work: Epitaxy release must connect to downstream device needs.","instruction":"整合厚度、摻雜、缺陷、粗糙與基板追溯表。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Combine thickness, doping, defects, roughness and substrate traceability. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"磊晶放行須連到後續元件需求；放行規格應固定所用缺陷定義。","observationEn":"Epitaxy release must connect to downstream device needs; Release specifications need fixed defect definitions.","failure":"若採用「只選缺陷密度最低批次而忽略其他規格」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Selecting minimum defect density while ignoring other requirements\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「磊晶放行」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：磊晶放行須連到後續元件需求。","checkEn":"Submit the Epitaxy release diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Epitaxy release must connect to downstream device needs.","knowledge":[{"id":"a081-v8-23-k1","title":"磊晶放行／物理與模型","titleEn":"Epitaxy release / Physics and model","text":"機制：磊晶放行須連到後續元件需求。","textEn":"Mechanism: Epitaxy release must connect to downstream device needs."},{"id":"a081-v8-23-k2","title":"磊晶放行／驗證與限制","titleEn":"Epitaxy release / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只選缺陷密度最低批次而忽略其他規格」。","textEn":"Model boundary: the current result does not establish the following claim: Selecting minimum defect density while ignoring other requirements."}],"quiz":{"question":"關於「磊晶放行」，哪項推論有物理依據？","questionEn":"For Epitaxy release, which inference has a physical basis?","options":["只看 Si:C 比就確認多型","磊晶放行須連到後續元件需求","只選缺陷密度最低批次而忽略其他規格"],"optionsEn":["Identifying polytype from Si:C ratio alone","Epitaxy release must connect to downstream device needs","Selecting minimum defect density while ignoring other requirements"],"answer":1,"explanation":"磊晶放行須連到後續元件需求；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Epitaxy release must connect to downstream device needs. The competing claim omits a necessary condition or mechanism."}},{"id":"a081-v8-24","order":6,"sequence":24,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-sic-gate","v8-c-sic-life","v8-c-sic"],"prerequisiteIds":["a081-v8-23"],"title":"磊晶放行：故障判讀與驗證","titleEn":"Epitaxy release: diagnose and verify","objective":"以新增對照檢查「只選缺陷密度最低批次而忽略其他規格」這項錯誤主張。","objectiveEn":"Test the faulty claim: Selecting minimum defect density while ignoring other requirements.","instruction":"接續前一步「磊晶放行」成果，先指出錯誤主張「只選缺陷密度最低批次而忽略其他規格」漏掉哪個條件。新增診斷原理：放行規格應固定所用缺陷定義。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Epitaxy release artifact. Identify the missing condition in the faulty claim \"Selecting minimum defect density while ignoring other requirements\". Introduce this diagnostic principle: Release specifications need fixed defect definitions. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"磊晶放行須連到後續元件需求；放行規格應固定所用缺陷定義。","observationEn":"Epitaxy release must connect to downstream device needs; Release specifications need fixed defect definitions.","failure":"若採用「只選缺陷密度最低批次而忽略其他規格」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Selecting minimum defect density while ignoring other requirements\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「磊晶放行」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「放行規格應固定所用缺陷定義」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Epitaxy release, its observable and one remaining uncertainty. Explain how \"Release specifications need fixed defect definitions\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a081-v8-24-k1","title":"磊晶放行／物理與模型","titleEn":"Epitaxy release / Physics and model","text":"診斷機制：放行規格應固定所用缺陷定義。","textEn":"Diagnostic mechanism: Release specifications need fixed defect definitions."},{"id":"a081-v8-24-k2","title":"磊晶放行／驗證與限制","titleEn":"Epitaxy release / Verification and limits","text":"可證偽性：「只選缺陷密度最低批次而忽略其他規格」與「磊晶放行須連到後續元件需求」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Selecting minimum defect density while ignoring other requirements\" is not equivalent to \"Epitaxy release must connect to downstream device needs\"; the control must expose their difference."}],"quiz":{"question":"檢查「磊晶放行」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Epitaxy release?","options":["只選缺陷密度最低批次而忽略其他規格","只看 Si:C 比就確認多型","放行規格應固定所用缺陷定義"],"optionsEn":["Selecting minimum defect density while ignoring other requirements","Identifying polytype from Si:C ratio alone","Release specifications need fixed defect definitions"],"answer":2,"explanation":"放行規格應固定所用缺陷定義；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Release specifications need fixed defect definitions. The competing claim omits a necessary condition or mechanism."}}]}],"subcategory":"compound","subcategoryTitle":"化合物與新材料元件","subcategoryTitleEn":"Compound and emerging devices"}};
